 return `<div class="cp-page w-${E(th.width||'normal')} f-${E(th.font||'default')}" dir="${dir}"${pst}>${hero?`<div class="cp-hero" style="background-image:url(&quot;${E(hero.replace(/["\\]/g,''))}&quot;)">${head}</div><div class="cp-inner">`:`<div class="cp-inner">${head}`}${blocks}</div></div>`;
