const CP_TYPES=['heading','text','button','buttons','image','gallery','card','video','divider','spacer','notice'],CP_RESERVED=new Set(['admin','api','app','asset','p','new']);
function cpU(v){v=String(v||'').trim().slice(0,2000);return /^(https?:\/\/|mailto:|tel:|\/(?!\/)|#)/i.test(v)?v:''}
function cpC(v){v=String(v||'').trim();return /^#[0-9a-f]{3,8}$/i.test(v)?v:''}
function cpS(v,n){return String(v??'').slice(0,n)}
