async function autoMatchTmdb(){if(tmdbMatching||!TMDB_CRED||!catalog?.length)return;tmdbMatching=true;try{overrides.settings=overrides.settings||{};let map=overrides.settings.tmdbMatches||{},weak=overrides.settings.tmdbWeak||{},targets=new Map();catalog.filter(x=>!x.tmdb_id).forEach(x=>{let title=x.series_name||x.title,key=(x.series_name?'series:':'title:')+normTitle(title)+'|'+String(x.year||'');if(title&&!map[key]&&!weak[key])targets.set(key,{title,year:x.year,type:x.series_name?'tv':'movie'})});let arr=[...targets];for(let n=0;n<arr.length;n+=4)await Promise.all(arr.slice(n,n+4).map(async([key,x])=>{try{let q=await tmdb(`/search/${x.type}?language=he-IL&query=${encodeURIComponent(x.title)}${x.year?'&year='+x.year:''}`),r=q?.results?.[0],date=r&&(r.release_date||r.first_air_date||''),same=normTitle(r&&(r.title||r.name))===normTitle(x.title),year=!x.year||!date||String(date).startsWith(String(x.year));if(r&&same&&year)map[key]=r.id;else weak[key]={candidate:r?.id||null,name:r&&(r.title||r.name)||'',checkedAt:new Date().toISOString()}}catch(e){}}));overrides.settings.tmdbMatches=map;overrides.settings.tmdbWeak=weak;catalog.forEach(x=>{if(x.tmdb_id)return;let key=(x.series_name?'series:':'title:')+normTitle(x.series_name||x.title)+'|'+String(x.year||'');if(map[key])x.tmdb_id=map[key]});if(arr.length){try{await saveOverrides()}catch(e){console.error('tmdb auto-match save',e.message)}}console.log('tmdb auto-match',Object.keys(map).length,'matched',Object.keys(weak).length,'review')}finally{tmdbMatching=false}}
let catalogEtag='',catalogModified='',catalogRefresh=null,catalogFailures=0,catalogRetryAfter=0;
function validCatalog(x){return Array.isArray(x)&&x.length>100&&x.every(v=>v&&typeof v==='object'&&(v.id!=null||v.custom_slug)&&typeof (v.title||v.series_name)==='string')}
function loadKanCatalog(){try{let p=path.join(ROOT,'kan-youtube.json'),d=JSON.parse(fs.readFileSync(p,'utf8'));kanCatalog=validCatalog(d)?d:[];clearCatalogCache();console.log('kan catalog',kanCatalog.length)}catch(e){console.error('kan catalog',e.message);kanCatalog=[]}}
async function loadCatalog(initial=false){if(catalogRefresh)return catalogRefresh;if(!initial&&Date.now()<catalogRetryAfter)return false;catalogRefresh=(async()=>{try{console.log('catalog refresh start',memoryMB());let headers={};if(catalogEtag)headers['if-none-match']=catalogEtag;if(catalogModified)headers['if-modified-since']=catalogModified;let r=await fetch(UPSTREAM,{headers,signal:AbortSignal.timeout(initial?60000:15000)});if(r.status===304){catalogFailures=0;catalogRetryAfter=0;console.log('catalog unchanged',memoryMB());return true}if(!r.ok)throw Error('HTTP '+r.status);let __jt=Date.now(),candidate=await r.json();console.log('[diag] catalog body+parse',(Date.now()-__jt)+'ms');if(!validCatalog(candidate))throw Error('catalog validation failed');catalog=candidate;clearCatalogCache();catalogEtag=r.headers.get('etag')||catalogEtag;catalogModified=r.headers.get('last-modified')||catalogModified;catalogFailures=0;catalogRetryAfter=0;console.log('catalog refreshed',catalog.length,memoryMB());return true}catch(e){catalogFailures++;catalogRetryAfter=Date.now()+Math.min(6*3600e3,15*60000*2**(catalogFailures-1));console.error('catalog refresh',e.message,'keeping last good');if(initial&&!catalog){let p=path.join(ROOT,'catalog.json');try{let fallback=JSON.parse(fs.readFileSync(p));catalog=validCatalog(fallback)?fallback:[];clearCatalogCache()}catch{catalog=[]}}return false}finally{catalogRefresh=null}})();return catalogRefresh}
loadKanCatalog();try{let fallback=JSON.parse(fs.readFileSync(path.join(ROOT,'catalog.json')));if(validCatalog(fallback))catalog=fallback}catch(e){console.error('fallback catalog',e.message)}server.listen(PORT,()=>console.log('Ariel Movies on',PORT));Promise.all([loadOverrides(),loadCatalog(true)]).catch(e=>console.error('startup load',e));process.on('unhandledRejection',e=>console.error('unhandled rejection',e&&e.stack||e));setInterval(()=>loadCatalog(false),60*60*1000).unref();setTimeout(()=>{fixSeriesTmdbMatches().catch(e=>console.error('tmdb series fix',e&&e.message))},90000);setInterval(()=>{fixSeriesTmdbMatches().catch(e=>console.error('tmdb series fix',e&&e.message))},24*3600*1000).unref();setTimeout(autoMatchTmdb,20000);setInterval(autoMatchTmdb,24*3600*1000).unref();
let analyticsDirty=0;
function ensureAnalytics(){overrides.analytics=overrides.analytics||{days:{},top:{},zeroSearch:{}};return overrides.analytics}
function recordStat(req,type,d){try{let a=ensureAnalytics(),day=new Date().toISOString().slice(0,10),DD=a.days[day]=a.days[day]||{views:0,plays:0,searches:0,visitors:[]};let h=crypto.createHash('sha256').update(requestIp(req)+'|'+(req.headers['user-agent']||'')+'|'+day+'|ariel-stats').digest('base64url').slice(0,16);if(!DD.visitors.includes(h)&&DD.visitors.length<8000)DD.visitors.push(h);if(type==='view')DD.views++;else if(type==='play'){DD.plays++;let id=String(d.id||'').slice(0,80);if(id){let t=a.top[id]=a.top[id]||{plays:0,title:''};t.plays++;if(d.title)t.title=String(d.title).slice(0,120)}}else if(type==='search'){DD.searches++;let q=String(d.q||'').trim().slice(0,80);if(q&&!(+d.results>0))a.zeroSearch[q]=(a.zeroSearch[q]||0)+1}let dk=Object.keys(a.days).sort();while(dk.length>45)delete a.days[dk.shift()];let tk=Object.entries(a.top).sort((x,y)=>y[1].plays-x[1].plays);if(tk.length>300)a.top=Object.fromEntries(tk.slice(0,300));let zk=Object.entries(a.zeroSearch).sort((x,y)=>y[1]-x[1]);if(zk.length>300)a.zeroSearch=Object.fromEntries(zk.slice(0,300));if(++analyticsDirty>=60){analyticsDirty=0;saveOverrides().catch(e=>console.error('analytics save',e.message))}}catch(e){console.error('stat',e.message)}}
